{
  "name": "@abix5/opencode-hindsight",
  "version": "0.7.0",
  "description": "Hindsight memory bank plugin for OpenCode",
  "type": "module",
  "main": "dist/index.js",
  "bin": {
    "opencode-hindsight": "./dist/cli.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "assets"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/abix5/opencode-hindsight.git"
  },
  "bugs": {
    "url": "https://github.com/abix5/opencode-hindsight/issues"
  },
  "homepage": "https://github.com/abix5/opencode-hindsight#readme",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "hindsight",
    "memory",
    "ai",
    "llm"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.4.12",
    "@opencode-ai/sdk": "^1.4.12",
    "@vectorize-io/hindsight-client": "^0.5.3"
  },
  "devDependencies": {
    "@types/node": "^25.2.1",
    "typescript": "^5.8.2",
    "vitest": "^4.0.18"
  }
}
